generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?catLabel 
       (SUM(?netCashFlow) AS ?totalNetCashFlow) 
       (AVG(?avgProgressPct) AS ?avgGoalProgress) 
       (SUM(?totalHoldingGain) AS ?totalHoldingGain) 
       (AVG(?avgRiskScore) AS ?avgRiskScore) 
       (AVG(?avgAllocationPct) AS ?avgAllocationPct)
WHERE {
  # Investor‑to‑Category mapping (one row per investor per category)
  {
    SELECT DISTINCT ?investorId ?category WHERE {
      ?ph a wm:PortfolioHolding .
      ?ph wm:investorId ?investorId .
      ?ph wm:hasCategory ?category .
    }
  }

  # Net cash flow per investor
  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?netCashFlow) WHERE {
      ?cf a wm:CashFlow .
      ?cf wm:investorId ?investorId .
      ?cf wm:amount ?amount .
    } GROUP BY ?investorId
  }

  # Goal progress per investor
  OPTIONAL {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avgProgressPct) WHERE {
      ?ig a wm:InvestmentGoal .
      ?ig wm:investorId ?investorId .
      ?ig wm:progressPct ?progressPct .
    } GROUP BY ?investorId
  }

  # Holding gain per investor
  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?totalHoldingGain) WHERE {
      ?ph2 a wm:PortfolioHolding .
      ?ph2 wm:investorId ?investorId .
      ?ph2 wm:currentValue ?cv .
      ?ph2 wm:cost ?cost .
      BIND (xsd:decimal(?cv) - xsd:decimal(?cost) AS ?gain)
    } GROUP BY ?investorId
  }

  # Risk score per investor
  OPTIONAL {
    SELECT ?investorId (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore) WHERE {
      ?ph3 a wm:PortfolioHealth .
      ?ph3 wm:investorId ?investorId .
      ?ph3 wm:riskScore ?riskScore .
    } GROUP BY ?investorId
  }

  # Allocation concentration per investor
  OPTIONAL {
    SELECT ?investorId (AVG(xsd:decimal(?allocationPct)) AS ?avgAllocationPct) WHERE {
      ?sa a wm:SectorAllocation .
      ?sa wm:investorId ?investorId .
      ?sa wm:allocationPct ?allocationPct .
    } GROUP BY ?investorId
  }

  # Category label (if available)
  OPTIONAL { ?category rdfs:label ?catLabel . }
}
GROUP BY ?catLabel
ORDER BY DESC(?totalNetCashFlow)

